*{box-sizing:border-box} :root{--ink:#24352d;--muted:#758278;--cream:#f6f4ec;--paper:#fffefa;--line:#e7e8df;--sage:#dfe9d7;--green:#415c43;--rust:#bb7959;--gold:#e7b967} body{margin:0;background:#f1f0e9;color:var(--ink);font-family:'DM Sans',sans-serif;font-size:14px;min-height:100vh}button{font:inherit;color:inherit}.game-shell{max-width:1390px;margin:auto;padding:0 40px}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #e1e3d9}.wordmark{font-size:11px;letter-spacing:.13em;text-transform:uppercase;text-decoration:none;color:#55685a;font-weight:700;display:flex;gap:10px;align-items:center}.wordmark i{font-style:normal;color:#b8b8a9}.brand-mark{display:grid;place-items:center;width:25px;height:25px;border:1px solid #9aab92;border-radius:50%;font-size:14px;color:#59745a}.top-note{font-size:12px;color:#78837b;letter-spacing:.02em;display:flex;align-items:center;gap:9px}.live-dot{height:7px;width:7px;background:#95ad80;border-radius:50%;box-shadow:0 0 0 4px #e2eadc}.sound-button{border:0;background:transparent;color:#607267;font-size:12px;cursor:pointer;padding:9px}.sound-button span{margin-left:5px}.game-grid{display:grid;grid-template-columns:minmax(0,1.58fr) minmax(340px,.82fr);gap:22px;padding:24px 0 16px}.scene-column{min-width:0}.scene{height:342px;position:relative;overflow:hidden;border-radius:10px;background:#82987e;isolation:isolate;box-shadow:0 5px 16px #32483312}.scene-sky{position:absolute;inset:0 0 38%;background:linear-gradient(180deg,#c3d0bb 0%,#e0d9b8 72%,#ead39c 100%);transition:background 1s}.sun{position:absolute;top:51px;left:57%;width:61px;height:61px;border-radius:50%;background:#f1d89d;box-shadow:0 0 45px 16px #f4e3b2a1}.distant-hill{position:absolute;bottom:39%;height:100px;width:60%;border-radius:50% 50% 0 0;background:#748a72;opacity:.72}.hill-one{left:-15%;transform:rotate(-5deg)}.hill-two{right:-16%;height:128px;background:#86977b;transform:rotate(8deg)}.moon{display:none;position:absolute;top:50px;left:60%;width:38px;height:38px;border-radius:50%;box-shadow:10px -5px 0 0 #f4e9c8}.stars{display:none;position:absolute;top:37px;left:13%;font-size:13px;color:#e9e9cc;letter-spacing:7px}.forest{position:absolute;bottom:30%;height:75%;width:100%;display:flex;align-items:end;justify-content:space-around;pointer-events:none}.forest i{display:block;width:0;height:0;border-left:38px solid transparent;border-right:38px solid transparent;border-bottom:154px solid #4d6954;position:relative;margin:0 -17px}.forest i:after{content:'';position:absolute;top:55px;left:-31px;border-left:31px solid transparent;border-right:31px solid transparent;border-bottom:106px solid #405b4a}.forest-back{bottom:36%;opacity:.64;transform:scale(.85)}.forest-back i{border-bottom-color:#617b62}.forest-back i:after{border-bottom-color:#536d59}.forest-front{z-index:2;bottom:22%;height:60%}.forest-front i{border-bottom-width:115px;border-left-width:32px;border-right-width:32px;border-bottom-color:#314a3a}.forest-front i:nth-child(even){transform:scale(.8);transform-origin:bottom}.forest-front i:after{top:42px;left:-25px;border-left-width:25px;border-right-width:25px;border-bottom-width:82px;border-bottom-color:#294336}.ground{position:absolute;bottom:0;left:0;right:0;height:31%;background:linear-gradient(180deg,#71856c,#536d55 72%,#48634d);z-index:1}.ground:before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse at 50% 0%,#afaa7180,transparent 58%)}.hut-wrap{position:absolute;z-index:3;bottom:20%;left:50%;width:220px;height:158px;transform:translateX(-34%)}.hut-roof{position:absolute;top:2px;left:12px;width:202px;height:82px;background:#785b43;clip-path:polygon(50% 0,100% 80%,92% 84%,5% 88%,0 79%);filter:drop-shadow(0 3px 1px #263d32)}.hut-roof:after{content:'';position:absolute;inset:0;background:repeating-linear-gradient(169deg,transparent 0 10px,#a37a4b 11px 13px,transparent 14px 19px);opacity:.8}.hut-body{position:absolute;bottom:0;left:33px;width:153px;height:103px;background:linear-gradient(90deg,#806047,#9b7752 48%,#775941);clip-path:polygon(0 0,100% 0,95% 100%,5% 100%);border-bottom:7px solid #654f3e}.hut-body:before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(0deg,transparent 0 11px,#c69c6947 12px 15px)}.hut-door{position:absolute;z-index:2;bottom:0;left:61px;width:45px;height:74px;border-radius:22px 22px 0 0;background:#344236;border:4px solid #73573f}.hut-window{position:absolute;z-index:2;right:17px;top:28px;width:22px;height:19px;border:2px solid #634c3b;border-radius:50%;background:#e8c77d}.hut-vine{position:absolute;inset:9px 5px 0;border-left:2px dashed #c09b61;opacity:.75}.hut-label{position:absolute;bottom:-21px;left:60px;color:#e1d7b6;font-size:7px;letter-spacing:.18em;white-space:nowrap}.smoke{position:absolute;z-index:4;top:5px;left:130px;display:flex;gap:3px;opacity:0;transition:.3s}.smoke i{width:7px;height:18px;border-radius:50%;background:#f2eee0;filter:blur(4px);animation:drift 2s infinite alternate}.smoke i:nth-child(2){animation-delay:.4s}.smoke i:nth-child(3){animation-delay:.8s}@keyframes drift{to{transform:translate(7px,-11px);opacity:.2}}.fire{position:absolute;z-index:4;bottom:19%;left:30%;width:30px;height:35px;display:none}.fire span,.fire i,.fire b,.fire small{position:absolute;bottom:0;left:8px;width:15px;height:22px;border-radius:70% 20% 65% 40%;background:#f1a652;transform:rotate(7deg);box-shadow:0 0 17px #f3a448}.fire i{left:12px;height:14px;background:#f9dd8c;transform:rotate(-10deg)}.fire b{bottom:-4px;left:-4px;width:40px;height:6px;border-radius:50%;background:#594536;box-shadow:none;transform:rotate(10deg)}.fire small{left:0;bottom:-6px;width:40px;height:6px;border-radius:50%;background:#594536;box-shadow:none;transform:rotate(-8deg)}.family{position:absolute;z-index:5;bottom:19%;left:25%;display:flex;align-items:end;gap:23px}.person{position:relative;width:45px;height:102px;filter:drop-shadow(1px 3px 2px #20372770)}.person .head{position:absolute;top:0;left:10px;width:27px;height:31px;background:#75482f;border-radius:45% 45% 47% 47%;z-index:3}.person .eye{position:absolute;width:3px;height:2px;background:#302720;top:13px;left:6px;border-radius:50%}.person .eye.second{left:18px}.smile{position:absolute;bottom:7px;left:10px;width:8px;height:4px;border-bottom:1px solid #d59b75;border-radius:50%}.hair{position:absolute;z-index:4;top:-3px;left:7px;width:32px;height:14px;background:#211e1a;border-radius:50% 50% 18% 16%}.mom-hair{height:19px;left:3px;width:38px;border-radius:45% 45% 23% 23%}.mom-hair:after{content:'';position:absolute;left:1px;top:8px;width:8px;height:19px;background:#211e1a;border-radius:0 0 5px 5px;box-shadow:27px 0 #211e1a}.body{position:absolute;top:28px;left:3px;width:40px;height:47px;background:#a77d50;clip-path:polygon(23% 0,77% 0,100% 100%,0 100%);z-index:2}.mom-body{height:49px;background:#9c7350}.kid-body{left:6px;width:34px;height:40px;background:#a6865a}.patch{position:absolute;top:12px;left:11px;width:12px;height:9px;border-radius:40%;background:#c59b67;opacity:.65}.arm{position:absolute;top:33px;left:0;width:8px;height:36px;background:#75482f;transform:rotate(11deg);border-radius:8px}.leg{position:absolute;z-index:1;bottom:0;left:12px;width:8px;height:30px;background:#75482f;border-radius:3px;transform:rotate(3deg)}.leg-b{left:27px;transform:rotate(-4deg)}.kid{transform:scale(.78);transform-origin:bottom}.kid .head{background:#86573b}.kid .leg,.kid .arm{background:#86573b}.snake-zone{display:none;position:absolute;z-index:6;left:54%;bottom:21%;color:#e5c884;font-size:24px;transform:rotate(-12deg)}.snake-eye{font-size:8px;position:absolute;top:4px;right:-2px;color:#f5e8b6}.scene-caption{z-index:7;position:absolute;bottom:12px;left:16px;display:flex;flex-direction:column;gap:3px;color:#f5f0d7;font-size:11px;text-shadow:0 1px 3px #334c3a}.caption-kicker{font-size:8px;letter-spacing:.16em;color:#d4d7b8;font-weight:700}.day-pill{position:absolute;z-index:7;right:15px;top:15px;padding:7px 10px;border-radius:30px;background:#f8f3dfc9;color:#62735c;font-size:8px;letter-spacing:.12em;font-weight:700;display:flex;gap:7px;align-items:center}.sun-icon{font-size:13px}.story-card{background:var(--paper);border:1px solid #e8e7dd;border-radius:9px;margin-top:14px;padding:19px 22px 15px;box-shadow:0 3px 12px #354a3710}.story-heading{display:flex;justify-content:space-between;align-items:center}.chapter-tag{font-size:9px;font-weight:700;color:#7a8b71;letter-spacing:.14em}.day-count{font-size:9px;letter-spacing:.12em;color:#a0a699;font-weight:700}.story-card h1{font-family:Fraunces,serif;font-weight:500;letter-spacing:-.03em;font-size:28px;line-height:1.15;margin:12px 0 6px;color:#304536}.story-card p{max-width:650px;font-size:12px;line-height:1.7;color:#768078;margin:0}.story-footer{display:flex;align-items:center;justify-content:space-between;margin-top:15px;padding-top:12px;border-top:1px solid #eef0e9}.weather{display:flex;align-items:center;gap:7px;color:#899187;font-size:10px}.weather-icon{font-size:15px;color:#b1a77d}.chapter-progress{display:flex;gap:4px}.chapter-progress i{width:16px;height:3px;background:#e8e9df;border-radius:8px}.chapter-progress i.active{background:#82977c}.side-column{display:flex;flex-direction:column;gap:11px}.panel{background:#fffefa;border:1px solid #e7e8df;border-radius:9px;padding:15px 16px;box-shadow:0 3px 12px #354a3708}.section-label{font-size:9px;font-weight:700;letter-spacing:.13em;color:#778678;display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.section-label>span:first-child:not(.tiny-muted){font-size:13px;color:#bb8a77}.tiny-muted{font-size:9px;letter-spacing:0;font-weight:500;color:#a4aaa0}.family-card{padding-bottom:10px}.family-row{display:flex;align-items:center;gap:10px;margin-bottom:10px}.avatar{height:32px;width:32px;border-radius:50%;display:grid;place-items:center;font-family:Fraunces,serif;color:#fff;font-size:13px;background:#826049}.kid-avatar{background:#687954}.person-info{display:flex;flex-direction:column;gap:3px;flex:1}.person-info strong{font-size:11px;font-weight:600}.person-info strong em{font-size:9px;font-style:normal;color:#9da49a;font-weight:500}.person-info small{font-size:9px;color:#959d93}.mood{color:#b7856e;font-size:12px}.mood small{font-size:9px;color:#a19f96}.kid-mood{color:#af9565}.heart-note{border-top:1px solid #f0eee6;padding:8px 0 0 41px;color:#9a8974;font-family:Fraunces,serif;font-style:italic;font-size:10px}.needs-card{padding-bottom:13px}.need-row{margin-top:11px}.need-label{display:flex;justify-content:space-between;font-size:10px;color:#778179;margin-bottom:6px}.need-label b{font-size:9px;color:#9ca498;font-weight:600}.meter{height:5px;background:#edf0e9;border-radius:8px;overflow:hidden}.meter i{height:100%;display:block;border-radius:8px;transition:width .5s}.energy-fill{background:#d6a86a}.food-fill{background:#8caa78}.hope-fill{background:#b18b8b}.inventory{display:flex;flex-wrap:wrap;gap:6px;min-height:25px;align-content:flex-start}.empty-inventory{font-size:10px;color:#a5aaa1;padding:2px 0 7px}.food-chip{padding:5px 8px;border-radius:20px;background:#f3f2e9;color:#65735b;font-size:9px;border:1px solid #ebeadd}.food-chip span{margin-right:4px}.wood-row{border-top:1px solid #f0eee6;padding-top:9px;margin-top:7px;display:flex;align-items:center;gap:8px;font-size:10px;color:#7f887d}.wood-icon{font-size:14px;color:#bb8662}.wood-row b{margin-left:auto;font-size:9px;font-weight:600;color:#9a9587}.actions-card{padding:15px 12px 10px}.actions-card .section-label{padding:0 4px;margin-bottom:6px}.action-list{display:flex;flex-direction:column}.action-button{border:0;background:transparent;border-top:1px solid #f1f0e9;display:flex;align-items:center;text-align:left;width:100%;padding:8px 3px;cursor:pointer;gap:9px;border-radius:4px;transition:background .15s}.action-button:hover:not(:disabled){background:#f8f8f1}.action-button:disabled{opacity:.42;cursor:not-allowed}.action-icon{width:28px;height:28px;display:grid;place-items:center;border-radius:8px;background:#eff2e9;font-size:18px;color:#72866a;flex:none}.gather-icon{background:#f2f0e5;color:#aa8e5e}.clear-icon{background:#f3eee6;color:#ae8464}.cook-icon{background:#f8eee4;color:#c18455}.rest-icon{background:#efedf1;color:#877991}.action-copy{display:flex;flex-direction:column;gap:3px;flex:1}.action-copy strong{font-size:10px;font-weight:600;color:#4b5c4d}.action-copy small{font-size:9px;color:#9aa097}.action-arrow{color:#9fa99a;font-size:13px}.end-day{width:100%;border:0;border-radius:6px;background:#526d52;color:#fffdf1;padding:11px 12px;margin-top:8px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;font-size:10px;font-weight:600;letter-spacing:.02em;transition:background .2s,transform .15s}.end-day:hover{background:#405b43;transform:translateY(-1px)}.end-day:disabled{opacity:.5;cursor:default;transform:none}.gentle-note{text-align:center;color:#a6a99f;font-size:9px;margin:9px 0 0}.site-footer{display:flex;justify-content:space-between;align-items:center;padding:11px 0 18px;font-size:9px;color:#a0a69b;letter-spacing:.03em}.site-footer button{border:0;background:none;color:#71816f;text-decoration:underline;text-underline-offset:2px;cursor:pointer;padding:0}.site-footer b{color:#879b79;margin-left:4px}.toast{position:fixed;left:50%;bottom:28px;z-index:20;transform:translate(-50%,20px);padding:11px 17px;background:#304536;color:#fffaf0;border-radius:7px;font-size:11px;box-shadow:0 5px 20px #1d302d30;opacity:0;pointer-events:none;transition:all .25s}.toast.show{opacity:1;transform:translate(-50%,0)}dialog{border:0;border-radius:12px;padding:0;max-width:420px;width:calc(100% - 32px);background:#fffefa;box-shadow:0 22px 70px #1e302d50;color:#304536}dialog::backdrop{background:#17291f88;backdrop-filter:blur(3px)}.modal-content{position:relative;padding:33px}.modal-close{position:absolute;right:14px;top:10px;border:0;background:transparent;color:#758278;font-size:24px;cursor:pointer}.modal-content h2{font:500 27px Fraunces,serif;margin:13px 0 8px}.modal-content p{font-size:12px;line-height:1.8;color:#7d877d}.modal-action{display:flex;justify-content:space-between;width:100%;margin-top:20px;padding:12px 14px;background:#526d52;color:#fff;border:0;border-radius:6px;cursor:pointer;font-size:11px}.night .scene-sky{background:linear-gradient(180deg,#233849,#354b51 75%,#86785c)}.night .sun{display:none}.night .moon,.night .stars{display:block}.night .distant-hill{background:#324a46}.night .forest-front i{border-bottom-color:#203a32}.night .forest-front i:after{border-bottom-color:#19352e}.night .ground{background:linear-gradient(180deg,#4b6452,#354b3c)}.night .scene-caption{color:#e9e6d3}.night .day-pill{background:#273c40;color:#e3ddbc}.night .sun-icon{font-size:12px}.snake-visible .snake-zone{display:block}.sad .mom-hair{background:#2b211e}.ending .scene{filter:saturate(.88)}
@media(max-width:950px){.game-shell{padding:0 22px}.game-grid{grid-template-columns:minmax(0,1.2fr) minmax(300px,.8fr);gap:14px}.scene{height:310px}.hut-wrap{transform:translateX(-29%)}.family{left:18%}.story-card{padding:17px}.side-column{gap:9px}.panel{padding:13px}.actions-card{padding:13px 10px 9px}}
@media(max-width:720px){.game-shell{padding:0 14px}.topbar{height:58px}.top-note{display:none}.game-grid{display:flex;flex-direction:column;padding-top:13px;gap:12px}.scene{height:clamp(245px,60vw,340px)}.scene .hut-wrap{transform:translateX(-32%) scale(.86);transform-origin:bottom center}.family{left:15%;transform:scale(.88);transform-origin:bottom}.scene-caption{bottom:10px}.story-card{margin-top:10px;padding:16px}.story-card h1{font-size:25px}.story-card p{font-size:11px}.side-column{display:grid;grid-template-columns:1fr 1fr;gap:9px}.family-card,.needs-card,.supplies-card,.actions-card{min-width:0}.actions-card{grid-column:1 / -1}.site-footer{font-size:8px;gap:6px}.site-footer span:last-child{display:none}.actions-card .action-button{padding:10px 4px}.action-copy strong{font-size:11px}.action-copy small{font-size:9px}.action-icon{width:31px;height:31px}.end-day{padding:13px}}
@media(max-width:390px){.game-shell{padding:0 10px}.scene{height:238px}.scene .hut-wrap{transform:translateX(-32%) scale(.72)}.family{left:12%;transform:scale(.72);transform-origin:bottom}.forest-front{transform:scale(.8)}.story-card{padding:13px}.story-card h1{font-size:22px}.side-column{gap:7px}.panel{padding:11px}.section-label{font-size:8px}.avatar{width:27px;height:27px}.person-info small{font-size:8px}.family-row{gap:7px}.mood{font-size:10px}.story-footer{margin-top:10px}.site-footer{padding-bottom:12px}}

(() => {
  const $ = (id) => document.getElementById(id);
  const buttons = [...document.querySelectorAll('.action-button')];
  const foods = [
    { name: 'wild berries', icon: '🫐', kind: 'forage' },
    { name: 'tender greens', icon: '🌿', kind: 'forage' },
    { name: 'mushrooms', icon: '🍄', kind: 'forage' },
    { name: 'steak', icon: '🥩', kind: 'market' },
    { name: 'onions', icon: '🧅', kind: 'market' },
    { name: 'bell peppers', icon: '🫑', kind: 'market' },
    { name: 'garlic', icon: '🧄', kind: 'market' },
    { name: 'peppercorn', icon: '🫒', kind: 'market' },
    { name: 'noodles', icon: '🍜', kind: 'market' },
    { name: 'crab', icon: '🦀', kind: 'market' },
    { name: 'lobster', icon: '🦞', kind: 'market' }
  ];
  const chapters = [
    {tag:'CHAPTER ONE · THE FIRST NIGHT', title:'A place to begin.', text:'You and Mom found a little shelter at the edge of the woods. The roof leans, and the path is unfamiliar. But it is somewhere to rest. You’re ten, and tonight you’ll make it a little safer together.'},
    {tag:'CHAPTER ONE · LEARNING THE PATHS', title:'Small things add up.', text:'The woods are starting to feel a little less unfamiliar. Mom takes her time on the long walk for food, and you look after the clearing. Together, you’re figuring out what helps.'},
    {tag:'CHAPTER TWO · MAKING IT SAFER', title:'A home takes tending.', text:'The hut is still rough, but it’s yours to care for. A swept path, a dry bundle of kindling, a meal shared by the fire: none of it is small.'},
    {tag:'CHAPTER TWO · A HARD DAY', title:'It’s okay to feel it.', text:'Some days are heavy. Mom gets quiet, and your eyes sting. You sit close, and she holds your hand. Being sad doesn’t mean you’ve stopped being brave.'},
    {tag:'CHAPTER THREE · STILL HERE', title:'You made a little home.', text:'The shelter has held through another night. The food is simple, the days take patience, and you keep finding ways to care for one another.'}
  ];
  const state = {};
  function freshState() {
    Object.assign(state, { day: 1, hours: 8, foods: [...foods.slice(0, 2)], wood: 1, energy: 68, fullness: 38, hope: 62, momMood: 'okay', kidMood: 'trying', cleared: false, cooked: false, searched: false, gatherCount: 0, meals: 0, snakeHandled: false, ended: false, finished: false, age: 10, time: 'EARLY MORNING' });
    document.body.classList.remove('night', 'snake-visible', 'ending');
    $('sceneCaption').textContent = 'The woods are quiet, for now.';
    $('weatherText').textContent = 'Clouds gathering beyond the trees';
    $('storyTitle').textContent = chapters[0].title;
    $('storyText').textContent = chapters[0].text;
    $('chapterTag').textContent = chapters[0].tag;
    $('dayCount').textContent = 'DAY 1';
    $('heartNote').textContent = 'You have each other. That counts for something.';
    $('momMood').innerHTML = '♡ <small>okay</small>';
    $('kidMood').innerHTML = '✦ <small>trying</small>';
    $('endDay').innerHTML = '<span>Settle in for the night</span><span>→</span>';
    $('endDay').disabled = false;
    $('timeLabel').textContent = state.time;
    render();
  }
  function toast(message) {
    const el = $('toast'); el.textContent = message; el.classList.add('show');
    clearTimeout(toast.timer); toast.timer = setTimeout(() => el.classList.remove('show'), 2200);
  }
  function setStory(title, text) { $('storyTitle').textContent = title; $('storyText').textContent = text; }
  function adjust(key, delta) { state[key] = Math.max(0, Math.min(100, state[key] + delta)); }
  function spend(hours, time) { state.hours -= hours; state.time = time; }
  function random(list) { return list[Math.floor(Math.random() * list.length)]; }
  function addFood(item) { state.foods.push(item); }
  function render() {
    $('energyValue').textContent = `${state.energy}%`; $('foodValue').textContent = `${state.fullness}%`; $('hopeValue').textContent = `${state.hope}%`;
    $('energyBar').style.width = `${state.energy}%`; $('foodBar').style.width = `${state.fullness}%`; $('hopeBar').style.width = `${state.hope}%`;
    $('woodCount').textContent = `${state.wood} ${state.wood === 1 ? 'bundle' : 'bundles'}`;
    $('basketCount').textContent = `${state.foods.length} ${state.foods.length === 1 ? 'thing' : 'things'}`;
    $('kidAge').textContent = state.age;
    $('hoursLeft').textContent = state.ended ? 'the day is done' : `${state.hours} hours left`;
    $('inventory').innerHTML = state.foods.length ? state.foods.map((f, i) => `<span class="food-chip" title="${f.name}"><span>${f.icon}</span>${f.name}</span>`).join('') : '<div class="empty-inventory">Nothing in the basket yet. There will be another chance.</div>';
    buttons.forEach(btn => {
      const action = btn.dataset.action;
      let cost = ({'mom-search':3, gather:2, clear:2, cook:4, rest:2})[action];
      let blocked = state.ended || state.finished || state.hours < cost;
      if (action === 'mom-search' && state.searched) blocked = true;
      if (action === 'clear' && state.cleared) blocked = true;
      if (action === 'cook' && (state.foods.length < 2 || state.wood < 1)) blocked = true;
      if (action === 'gather' && state.gatherCount >= 2) blocked = true;
      btn.disabled = blocked;
      if (action === 'mom-search' && state.searched) btn.querySelector('small').textContent = 'Mom is home for today · rest her feet';
      else if (action === 'clear' && state.cleared) btn.querySelector('small').textContent = 'The path is clear and checked';
